const CACHE='cornerwork-v1';
const CORE=['./','./index.html','./features.css','./features.js','./manifest.webmanifest','./icon.svg','./apple-touch-icon.png','./icon-192.png','./icon-512.png'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(CORE)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET')return;const url=new URL(event.request.url),cacheable=url.origin===location.origin||['www.gstatic.com','cdn.jsdelivr.net','accounts.google.com'].includes(url.hostname);event.respondWith(caches.match(event.request).then(cached=>cached||fetch(event.request).then(response=>{if(cacheable&&(response.ok||response.type==='opaque')){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy))}return response}).catch(()=>url.origin===location.origin?caches.match('./index.html'):Promise.reject())))});
